// Memory arenas enumeration. Region IDs come from the render plan's
// deterministic ordering policy (scratch < persistent < constant;
// within-role: memory.name ascending) so two re-plans of the same
// model produce identical enum values. The PLAN_HASH macro above
// fingerprints the same ordering for ABI drift detection.
typedef enum {
    hkv_arrhythmia_arena_sram = 0,
    hkv_arrhythmia_arena_const_mram = 1,
    hkv_arrhythmia_num_arena_buffers = 2
} hkv_arrhythmia_arena_region_t;

// Runtime status codes returned by the generated C API.
//
// Numeric values are organized into namespaced ranges so callers can
// disambiguate which API surface produced an error without
// out-of-band context:
//
//   * 0          : success.
//   * 1..4       : per-region ``hkv_arrhythmia_bind_arena`` failures
//                  (also forwarded by ``hkv_arrhythmia_bind_arenas`` for
//                  per-region issues).
//   * 10..12     : ``hkv_arrhythmia_context_init`` /
//                  ``hkv_arrhythmia_hydrate_constants`` preconditions.
//   * 13         : common ``ctx == NULL`` precondition failure
//                  shared across every public entry point.
//   * 14         : lifecycle precondition (``model_run`` before
//                  successful ``model_init``).
//   * 100..109   : ``hkv_arrhythmia_bind_arenas`` bulk-argument failures.
//   * 200..209   : ``hkv_arrhythmia_model_run`` precondition failures
//                  (e.g. hydration latch).
//
// Code that needs to inspect status values should prefer the
// enumerator names below; raw literals are reserved for snapshot /
// ABI-stability tests.
typedef enum {
    hkv_arrhythmia_status_ok = 0,

    // bind_arena() per-region failures.
    hkv_arrhythmia_status_bind_unknown_region   = 1,
    hkv_arrhythmia_status_bind_null_buffer      = 2,
    hkv_arrhythmia_status_bind_undersized       = 3,
    hkv_arrhythmia_status_bind_misaligned       = 4,

    // context_init() / hydrate_constants() failures.
    hkv_arrhythmia_status_context_arena_unbound = 10,
    // hydrate_constants() called on a context whose arena_buffers
    // table is still NULL (i.e. before context_init succeeded).
    hkv_arrhythmia_status_hydrate_uninited_context = 11,
    hkv_arrhythmia_status_hydrate_null_blob     = 12,

    // Common precondition failure (any public entry point).
    hkv_arrhythmia_status_null_context          = 13,
    // model_run() called before model_init() succeeded.
    hkv_arrhythmia_status_not_initialized       = 14,

    // bind_arenas() bulk-argument failures (per-region failures
    // forward the 1..4 range above).
    hkv_arrhythmia_status_bind_bulk_null_argument = 100,
    hkv_arrhythmia_status_bind_bulk_wrong_count   = 101,

    // model_run() precondition failures.
    hkv_arrhythmia_status_hydration_required = 200,
} hkv_arrhythmia_status_t;

// Tensor categories
typedef enum {
    hkv_arrhythmia_tensor_type_constant,
    hkv_arrhythmia_tensor_type_persistent,
    hkv_arrhythmia_tensor_type_scratch,
} hkv_arrhythmia_tensor_type_t;

// Tensor descriptors. Every tensor — scratch, persistent, or
// constant — is bound to an arena slot. The kernel-visible address
// is always ``arena_buffers[region] + offset``. There are no
// per-tensor C symbols.
typedef struct {
    hkv_arrhythmia_tensor_type_t type;
    hkv_arrhythmia_arena_region_t region;
    size_t offset;
    size_t size;
} hkv_arrhythmia_tensor_descriptor_t;

